import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const moduleRequire = createRequire(import.meta.url);

// Where a prebuilt helper can live: next to the installed package, next to
// this module, and next to the executable.
export function getNativeModuleCandidates(nativePath, options = {}) {
  const moduleDir = dirname(fileURLToPath(options.moduleUrl ?? import.meta.url));
  const candidates = [];
  try {
    const entry = (options.resolvePackage ?? moduleRequire.resolve)("native-helper");
    candidates.push(join(dirname(entry), "..", nativePath));
  } catch {
    // A standalone executable has no installed package.
  }
  candidates.push(join(moduleDir, "..", nativePath), join(moduleDir, nativePath));
  return Array.from(new Set(candidates));
}
